def _vjs(value: Any) -> str:
    # JSON encoding for scalars (ids, kinds, hex64 strings, timestamps).
    return json.dumps(value, ensure_ascii=False)


def _vtype_key(value: Any) -> Any:
    """Type-faithful structural identity of a leaf credential value.

    The reuse registry must never merge values whose compact JSON text
    merely *looks* equal while their Python types differ: an integer fact
    or condition key and the string with the same digits, a tuple and the
    list with the same items, ``True`` and ``1``.  This key walks the
    value once and records the real type of every container and key, so
    only values equal in both type and value share an identity; anything
    else falls through to full validation, which rejects it.  Dict item
    order is normalized away by sorting on the (type-tagged) keys, and
    every legal credential contains only dicts, lists, strings, bools,
    ints, and nulls, for which the key is exact.  This is a structural
    walk, not a serialization: no text or byte form of the value is
    produced for keying.
    """
    if isinstance(value, dict):
        items = [
            (_vtype_key(key), _vtype_key(item)) for key, item in value.items()
        ]
        items.sort()
        return ("dict", tuple(items))
    if isinstance(value, list):
        return ("list", tuple(_vtype_key(item) for item in value))
    if isinstance(value, tuple):
        return ("tuple", tuple(_vtype_key(item) for item in value))
    if isinstance(value, str):
        return ("str", value)
    if isinstance(value, bool):
        return ("bool", value)
    if isinstance(value, int):
        return ("int", value)
    if isinstance(value, float):
        return ("float", value)
    if value is None:
        return ("none",)
    return ("other", type(value).__qualname__, repr(value))

